# --- Helper Functions ---
def extract_selectors(css_content: str) -> list[str]:
    """Extract all CSS selectors from the stylesheet."""
    # Remove comments
    css_no_comments = re.sub(r"/\*.*?\*/", "", css_content, flags=re.DOTALL)
    # Match selector blocks (everything before {)
    selectors = re.findall(r"([^{}]+)\{", css_no_comments)
    # Flatten comma-separated selectors
    flat_selectors = []
    for selector_group in selectors:
        for selector in selector_group.split(","):
            selector = selector.strip()
            if selector:
                flat_selectors.append(selector)
    return flat_selectors


def extract_class_names(css_content: str) -> set[str]:
    """Extract all class names from the CSS content."""
    return set(re.findall(r"\.([a-zA-Z_][a-zA-Z0-9_-]*)", css_content))


def extract_custom_properties(css_content: str) -> set[str]:
    """Extract all custom property names (CSS variables)."""
    return set(re.findall(r"(--[a-zA-Z0-9_-]+)\s*:", css_content))


def extract_media_queries(css_content: str) -> list[str]:
    """Extract all media query conditions."""
    return re.findall(r"@media\s*([^{]+)\{", css_content)


def extract_declarations(css_content: str) -> list[str]:
    """Extract all property declarations from the CSS."""
    # Remove comments and media query wrappers (simplified)
    css_no_comments = re.sub(r"/\*.*?\*/", "", css_content, flags=re.DOTALL)
    # Find all property: value; pairs
    return re.findall(r"([a-zA-Z-]+)\s*:\s*([^;]+);", css_no_comments)


def hex_to_rgb(hex_color: str) -> tuple[int, int, int] | None:
    """Convert hex color to RGB tuple."""
    hex_color = hex_color.strip().lstrip("#")
    if len(hex_color) == 3:
        hex_color = "".join(c * 2 for c in hex_color)
    if len(hex_color) != 6:
        return None
    try:
        return tuple(int(hex_color[i : i + 2], 16) for i in (0, 2, 4))  # type: ignore[return-value]
    except ValueError:
        return None


def relative_luminance(rgb: tuple[int, int, int]) -> float:
    """Calculate relative luminance per WCAG 2.1."""
    r, g, b = [c / 255.0 for c in rgb]
    r = r / 12.92 if r <= 0.03928 else ((r + 0.055) / 1.055) ** 2.4
    g = g / 12.92 if g <= 0.03928 else ((g + 0.055) / 1.055) ** 2.4
    b = b / 12.92 if b <= 0.03928 else ((b + 0.055) / 1.055) ** 2.4
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def contrast_ratio(rgb1: tuple[int, int, int], rgb2: tuple[int, int, int]) -> float:
    """Calculate WCAG contrast ratio between two colors."""
    lum1 = relative_luminance(rgb1)
    lum2 = relative_luminance(rgb2)
    lighter = max(lum1, lum2)
    darker = min(lum1, lum2)
    return (lighter + 0.05) / (darker + 0.05)


def extract_colors(css_content: str) -> dict[str, str]:
    """Extract color values from CSS custom properties."""
    colors = {}
    for match in re.finditer(r"(--[a-zA-Z0-9_-]+)\s*:\s*(#[0-9a-fA-F]{3,8})\s*;", css_content):
        colors[match.group(1)] = match.group(2)
    return colors


