    def test_color_contrast_aa(self, css_content: str):
        """Text colors must meet WCAG AA contrast ratio (4.5:1)."""
        colors = extract_colors(css_content)
        if not colors:
            pytest.skip("No hex colors found in custom properties")

        # Check text color vs background
        text_color = colors.get("--chart-text")
        bg_color = colors.get("--chart-bg", "#ffffff")
        if text_color and bg_color:
            text_rgb = hex_to_rgb(text_color)
