class TestPerformance:
    """Validate CSS performance characteristics."""

    def test_declaration_density(self, declarations: list[str], css_content: str):
        """Declaration density should be reasonable (< 200 declarations)."""
        assert len(declarations) < 200, f"Too many declarations: {len(declarations)}"

    def test_selector_complexity(self, selectors: list[str]):
        """Selectors should not be overly complex (max 3 levels deep)."""
        for selector in selectors:
            depth = selector.count(" ") + selector.count(">") + selector.count("+") + selector.count("~")
            assert depth <= 3, f"Overly complex selector: {selector} (depth {depth})"

    def test_no_universal_selectors(self, css_content: str):
        """Avoid universal selectors (*) for performance."""
        universal = re.findall(r"(?<![\w-])\*(?![\w-])", css_content)
        assert not universal, "Universal selectors (*) found"

    def test_no_important_overuse(self, css_content: str):
        """!important should be used sparingly (max 5)."""
        important_count = css_content.count("!important")
        assert important_count <= 5, f"Too many !important declarations: {important_count}"

    def test_no_inline_style_blocks(self, css_content: str):
        """No inline style attributes in CSS."""
        assert "style=" not in css_content, "Inline style attributes found"

    def test_selector_reuse(self, class_names: set[str], selectors: list[str]):
        """Classes should be reused, not duplicated."""
        class_usage = Counter()
        for selector in selectors:
            for cls in re.findall(r"\.([a-zA-Z_][a-zA-Z0-9_-]*)", selector):
                class_usage[cls] += 1
        unused = class_names - set(class_usage.keys())
        assert not unused, f"Unused class names: {unused}"


